"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[7340],{7340:a=>{a.exports=JSON.parse('{"meta":{"title":"Skill Alexa Muslim Companion: Azan di Echo Anda - iMuslim Life","description":"Muslim Companion memutar azan di Amazon Echo pada waktu salat Anda, dengan Al-Qur\'an, zikir, Hifz Coach, dan mode Ramadan. Gratis. Atur di alexa.imuslimlife.com."},"hero":{"title":"Muslim Companion untuk Alexa","lede":"Azan pada waktu salat setempat, zikir setelah salat, tilawah Al-Qur\'an, dan pengingat dari masjid Anda, di Amazon Echo Anda.","live":"\u2714 Sudah tersedia di Alexa","dashboard":"Buka Dasbor","tryWeb":"Coba Aplikasi Web","imgAlt":"Perangkat Amazon Alexa","athan":"\\"Allahu Akbar...\\"","maghrib":"Magrib pukul 19.45"},"how":{"h2":"Cara Kerjanya","sub":"Siapkan muazin pribadi Anda dalam tiga langkah mudah, kurang dari lima menit.","s1":{"h3":"Aktifkan Skill","p":"Buka aplikasi Alexa di ponsel, cari <b>Muslim Companion</b>, lalu ketuk <i>Enable to Use</i>. Kemudian ucapkan dalam bahasa Inggris \\"<q>{{p1}}</q>\\" (Alexa, buka Muslim Companion) untuk konfirmasi."},"s2":{"h3":"Masuk & Atur","p":"Kunjungi <a>alexa.imuslimlife.com</a>, masuk, konfirmasi lokasi, pilih suara azan, dan ikuti masjid Anda (misalnya AMCC) untuk pengingat iqamah dan Jumat.","voice":"<b>Atau dengan suara:</b> \\"<q>{{p1}}</q>\\" (atur metode perhitungan ke ISNA) dan \\"<q>{{p2}}</q>\\" (atur mazhab ke Hanafi), tanpa dasbor. Lihat perintah suara di bawah."},"s3":{"h3":"Buat Rutinitas & Nikmati","p":"Di aplikasi Alexa, buat satu rutinitas: saat sensor <i>Muslim Companion Azan</i> terbuka, buka <i>Muslim Companion</i>. Echo Anda lalu memutar azan otomatis di setiap waktu salat. <a>Panduan penyiapan langkah demi langkah</a> kami menuntun Anda dengan tangkapan layar."}},"features":{"h2":"Fitur Utama","sub":"Semuanya diatur di alexa.imuslimlife.com, dan setiap fitur tambahan mati sampai Anda menyalakannya","soon":"Segera hadir: ditinjau ulama","items":{"athan":{"title":"Azan pada waktu salat Anda","description":"Echo Anda memutar azan pada waktu setempat untuk kelima salat, dengan pilihan suara muazin dan azan khusus Subuh."},"masjid":{"title":"Masjid Connect","description":"Ikuti masjid Anda (seperti AMCC) dan dapatkan pengingat sebelum setiap iqamah dan sebelum Jumat, sesuai jadwal yang diterbitkan masjid."},"quran":{"title":"Tilawah Al-Qur\'an","description":"Lebih dari 30 qari ternama. Satu surah setelah azan, atau Al-Qur\'an diputar sepanjang hari, dan lanjutkan dari terakhir kali."},"adhkar":{"title":"Zikir setelah salat","description":"Ayat Kursi dan tiga Qul setelah setiap salat, dengan teks Arab dan terjemahan Inggris atau Urdu. Mati sampai Anda menyalakannya."},"hifz":{"title":"Hifz Coach","description":"Hafalkan beberapa ayat sekaligus di Echo: setiap ayat tiga kali, lalu seluruh pelajaran bersama, dengan kemajuan tersimpan. Berlatih juga secara online."},"ramadan":{"title":"Mode Ramadan","description":"Pengingat sahur sebelum Subuh, pengumuman berbuka saat Magrib, dan tilawah tarawih Makkah setelah Isya."},"show":{"title":"Layar Echo Show","description":"Jadwal salat hari ini di layar dengan salat berikutnya disorot dan hitung mundur, plus widget Jadwal Salat yang selalu tampil."},"scenes":{"title":"Suasana Rumah","description":"Redupkan lampu saat azan, bangun perlahan sebelum Subuh, atau ciptakan malam yang tenang setelah Isya, dengan rutinitas Alexa Anda sendiri."},"duas":{"title":"Doa setelah azan","description":"Doa setelah azan dan doa pilihan Anda, diputar di Echo tepat setelah azan."},"qibla":{"title":"Arah kiblat","description":"Tanyakan arah kiblat: arah dari rumah Anda dalam derajat dan arah mata angin, serta jarak ke Makkah."},"hijri":{"title":"Tanggal Hijriah & kalender Islam","description":"Tanggal Hijriah hari ini, dan berapa hari lagi menuju Ramadan, Idul Fitri/Adha, Asyura, Arafah, atau ayyamul bidh. Tanggal yang sama dengan jadwal salat Anda."},"fasting":{"title":"Puasa sunah","description":"Tanyakan kapan puasa sunah berikutnya, atau dapatkan pengingat setelah Isya pada malam sebelum Senin, Kamis, ayyamul bidh, Arafah, dan Asyura."},"tasbih":{"title":"Tasbih & zikir pagi dan petang","description":"Alexa menghitung zikir bersama Anda (33, 33, 34 setelah salat), dengan penghitung sentuh di Echo Show, dan memutar zikir pagi dan petang."},"translation":{"title":"Al-Qur\'an dengan terjemahan","description":"Putar surah apa pun dengan suara, dengan terjemahan Inggris atau Urdu setelah setiap ayat, dan Surah Al-Kahfi setiap Jumat."},"daily":{"title":"Doa, Hadis & Asmaul Husna harian","description":"Satu doa pendek, hadis, atau salah satu dari 99 Nama setiap hari, dengan sumbernya, ditinjau ulama sebelum diterbitkan."}}},"screens":{"h2":"Lihat cara kerjanya","sub":"Layar asli dari keluarga yang mengikuti AMCC di Florida: jadwal salat untuk lokasi mereka sendiri, dan waktu iqamah yang diterbitkan masjid.","showAlt":"Layar Echo Show: jadwal salat hari ini dengan iqamah masjid, dan salat berikutnya, Magrib, disorot dengan hitung mundur","showH":"Di Echo Show Anda","showP":"Ucapkan \\"<q>{{p1}}</q>\\" (tanyakan jadwal salat hari ini ke Muslim Companion): lima salat dan matahari terbit, iqamah masjid Anda di samping masing-masing, dan salat berikutnya disorot dengan hitung mundur.","phoneAlt":"Masjid Saya di ponsel: masjid, waktu azan dan iqamah hari ini, Jumat, dan pilihan pengingat Echo","phoneH":"Di ponsel Anda","phoneP":"Di <a>alexa.imuslimlife.com</a>, buka <b>Masjid Saya</b> dan pilih masjid Anda. Anda melihat waktu azan dan iqamah hari ini serta Jumat minggu ini, dan memilih kapan Echo mengingatkan Anda sebelum iqamah dan Jumat.","widgetAlt":"Widget Jadwal Salat: salat berikutnya Magrib dengan hitung mundur, waktu iqamah, dan lima salat hari ini","widgetH":"Widget yang selalu tampil","widgetP":"Di Echo Show 8, 10, dan 15, tambahkan widget <b>Jadwal Salat</b>: salat berikutnya, hitung mundurnya, dan iqamah masjid Anda tetap di layar utama."},"voice":{"h2":"Perintah Suara","sub":"Semua yang bisa Anda ucapkan ke Muslim Companion, dikelompokkan per fitur. Memakai asisten AI? <a>Hubungkan ke jadwal salat kami</a>."},"ref":{"langsTitle":"Bahasa dan negara","langsBody":"Muslim Companion memahami bahasa <b>Inggris</b>, <b>Arab</b> (\\"\u0627\u0644\u0631\u0641\u064a\u0642 \u0627\u0644\u0645\u0633\u0644\u0645\\"), dan <b>Hindi</b> (\\"\u092e\u0941\u0938\u094d\u0932\u093f\u092e \u0915\u092e\u094d\u092a\u0948\u0928\u093f\u092f\u0928\\"). Dalam bahasa Inggris, ucapkan kalimatnya persis seperti tertulis, diawali \\"<q>{{p1}}</q>\\" (namanya sama di <b>Amerika Serikat, Kanada, Inggris, India, dan Australia</b>). Pilih bahasa di atas untuk melihat kalimat Arab atau Hindi. Jika kalimat punya pilihan, seperti metode perhitungan, deskripsinya mencantumkan semua opsi.","soonNote":"Perintah bertanda <b>Segera hadir</b> belum tersedia; lencananya menjelaskan alasannya.","english":"English","soonSuffix":" \xb7 segera hadir","langNote":"<b>{{title}}</b>: atur bahasa Alexa ke {{lang}} untuk memakai Muslim Companion dalam bahasa tersebut. Nama skill dalam bahasa ini adalah <n>{{name}}</n>. Inilah kalimat persis yang dipahaminya; deskripsinya tetap dalam bahasa Inggris.","langAr":"Arab (Arab Saudi)","langHi":"Hindi (India)","all":"Semua","comingSoon":"Segera hadir","showsOnShow":"Tampil di Echo Show","whilePlaying":"Saat Muslim Companion sedang diputar","turnsOff":"Mematikan azan otomatis","tip":"Tips: {{tip}}","footer":"Anda juga bisa memulai dengan \\"<q>{{p1}}</q>\\" (Alexa, buka Muslim Companion) lalu bertanya. Perintah seperti \\"<q>next</q>\\" (berikutnya), \\"<q>pause</q>\\" (jeda), dan \\"<q>stop</q>\\" (berhenti) berfungsi saat Muslim Companion sedang diputar."},"api":{"h2":"Didukung API Kami yang Teruji","p":"Skill Alexa Muslim Companion dibangun di atas API jadwal salat kami yang andal, dengan perhitungan tepat berdasarkan lokasi persis Anda.","methods":{"primary":"23 Metode Perhitungan + Asar Hanafi atau Standar","secondary":"ISNA, Liga Muslim Dunia, Umm al-Qura, Mesir, Karachi, Teluk, Kuwait, Qatar, Singapura, Prancis, Turki, Rusia, Teheran, dan Jafari, diatur di dasbor atau dengan suara"},"hijri":{"primary":"Integrasi Kalender Hijriah","secondary":"Tanggal Islam yang akurat bersama jadwal salat"},"perf":{"primary":"Performa Tinggi","secondary":"Dioptimalkan untuk kecepatan dan keandalan"},"free":{"primary":"Gratis untuk Umat","secondary":"API jadwal salat gratis digunakan"},"cta":"Jelajahi API Kami","imgAlt":"Ilustrasi API"},"cta":{"h2":"Siap mendengar azan dari Alexa?","p":"Skill sudah tersedia. Atur jadwal salat pribadi Anda dalam kurang dari lima menit.","guide":"Lihat Panduan Penyiapan","small":"Gratis selamanya \xb7 Tanpa unduh aplikasi \xb7 Berfungsi di semua perangkat Echo"},"faq":{"h2":"Pertanyaan Umum","devices":{"q":"Perangkat Alexa apa saja yang didukung skill ini?","a":"Skill Muslim Companion berfungsi di semua perangkat Amazon Echo atau perangkat yang mendukung Alexa. Untuk suara terbaik, kami menyarankan perangkat dengan speaker berkualitas seperti Echo, Echo Dot, atau Echo Show."},"dst":{"q":"Apakah skill menyesuaikan otomatis dengan waktu musim panas?","a":"Ya, skill otomatis menyesuaikan jadwal salat dengan zona waktu lokasi Anda dan perubahan waktu musim panas. Anda selalu mendapat jadwal akurat tanpa penyesuaian manual."},"choose":{"q":"Bisakah saya memilih salat mana yang memutar azan?","a":"Tentu! Anda bisa memilih salat mana yang memutar azan, misalnya hanya Subuh, Magrib, dan Isya, atau kelima salat. Pilih di halaman Pengaturan Salat di alexa.imuslimlife.com."},"cost":{"q":"Apakah skill ini berbayar?","a":"Skill Muslim Companion sepenuhnya gratis. Fungsi intinya, jadwal salat akurat dan azan otomatis, tetap gratis untuk umat Muslim, selamanya."},"offline":{"q":"Bagaimana jika koneksi internet terputus?","a":"Jadwal salat dihitung lebih dahulu, tetapi Echo membutuhkan internet untuk memutar azan. Jika koneksi terputus saat waktu salat, azan tersebut bisa terlewat; semuanya berlanjut otomatis setelah koneksi kembali."}},"films":{"eyebrow":"Lihat langsung","title":"Siapkan Muslim Companion dalam kurang dari satu menit","athan":{"tab":"Azan di setiap salat","length":"1 mnt","play":"Putar video penyiapan azan","p1":"Aktifkan skill","p2":"Alexa menemukan sensor","p3":"Buat rutinitas","cta":"Buka dasbor","after":"Setelah rutinitas disimpan, selesaikan penyiapan: masuk di alexa.imuslimlife.com, atau buka aplikasi Salat-e-Mustaqeem dan ketuk ikon Alexa."},"quran":{"tab":"Al-Qur\'an setelah setiap azan","length":"40 dtk","play":"Putar video penyiapan jadwal Al-Qur\'an","p1":"Qari pilihan Anda","p2":"Surah pertama Anda","p3":"Al-Kahfi setiap Jumat","badge":"Streaming 24/7 di Alexa","after":"Pilih qari, surah awal, dan apa yang diputar berikutnya. Azan berikutnya selalu didahulukan, jadi bacaan tidak pernah memasuki waktu salat.","cta":"Siapkan jadwal Al-Qur\'an"}},"widgets":{"soon":"Segera hadir","h3":"Delapan widget baru untuk Echo Show","sub":"Pilih tampilan favorit untuk layar beranda Anda. Widget ini sedang ditinjau Amazon dan akan muncul di galeri widget Echo Show Anda setelah disetujui.","items":{"mihrab":{"name":"Jendela mihrab","desc":"Salat berikutnya dalam bingkai jendela melengkung, dengan hitung mundurnya.","alt":"Widget Jendela mihrab untuk Echo Show"},"sun-arc":{"name":"Busur matahari","desc":"Matahari bergerak sepanjang hari dari Subuh hingga Isya, jadi posisi Anda terlihat sekilas.","alt":"Widget Busur matahari untuk Echo Show"},"lamps":{"name":"Lima pelita","desc":"Satu pelita untuk tiap salat; pelita salat berikutnya menyala keemasan.","alt":"Widget Lima pelita untuk Echo Show"},"illuminated":{"name":"Halaman iluminasi","desc":"Salat berikutnya dalam kaligrafi Arab emas, di halaman bergaya manuskrip.","alt":"Widget Halaman iluminasi untuk Echo Show"},"timetable":{"name":"Jadwal cetak","desc":"Kelima salat dalam tabel cetak yang rapi, dengan salat berikutnya ditandai.","alt":"Widget Jadwal cetak untuk Echo Show"},"ink-arch":{"name":"Lengkung tinta","desc":"Lengkung bergambar tinta di sekitar salat berikutnya dan hitung mundurnya.","alt":"Widget Lengkung tinta untuk Echo Show"},"ayah":{"name":"Ayat Hari Ini","desc":"Ayat baru setiap hari dalam bahasa Arab dengan maknanya dalam bahasa Inggris (Saheeh International).","alt":"Widget Ayat Hari Ini untuk Echo Show"},"now-reciting":{"name":"Sedang Dibacakan","desc":"Surah dan qari yang diputar di Echo Anda, langsung di layar beranda.","alt":"Widget Sedang Dibacakan untuk Echo Show"}},"readAlongH":"Membaca bersama Mushaf","readAlongP":"Juga sedang ditinjau: ikuti bacaan di halaman Mushaf pada Echo Show, setiap kata disorot saat dibacakan. Ketuk sebuah kata untuk melompat ke ayatnya."}}')}}]);